using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "GainEffectBasedOnAstriumCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Orion/GainEffectBasedOnAstriumCustomDescription", order = 0)]
public class GainEffectBasedOnAstriumCustomDescription : CustomBattleActionDescription
{
	private const string synthetizationGainAstriumIfLessThanXAstriumID = "SynthetizationGainAstriumIfLessThanXAstrium";

	private const string synthetizationBaseID = "SynthetizationBase";

	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		GainEffectBasedOnAstriumAction gainEffectBasedOnAstriumAction = battleAction as GainEffectBasedOnAstriumAction;
		string firstArgument = Smart.Format(base.localizationManager.GetLocalizedCastOrbActionBase(), gainEffectBasedOnAstriumAction.OrbToCast.StarAbilityID.GetSpriteText() + gainEffectBasedOnAstriumAction.OrbToCast.GetLocalizedNameWithoutModifiers());
		firstArgument = base.localizationManager.GetLocalizedXTimesFormatted(firstArgument, gainEffectBasedOnAstriumAction.OrbCastAmount);
		return Smart.Format(base.localizationManager.GetLocalizedString("SynthetizationGainAstriumIfLessThanXAstrium"), 9, 1) + "\n" + base.localizationManager.GetLocalizedWhereX(gainEffectBasedOnAstriumAction.GainEffectAction.GetActionDescription(-1).RemoveLast(), y: false, Smart.Format(base.localizationManager.GetLocalizedString("SynthetizationBase"), base.localizationManager.GetLocalizedRoundedUp())) + "\n" + firstArgument;
	}
}
